<?php
require_once __DIR__ . '/../includes/auth.php'; require_role(['admin']);
$status = get_str('status', 'all'); $allowed = ['all', 'published', 'under_review', 'removed']; if (!in_array($status, $allowed, true)) $status = 'all'; $where = $status === 'all' ? '1=1' : 'r.status = ?'; $params = $status === 'all' ? [] : [$status];
$count = $pdo->prepare("SELECT COUNT(*) FROM resources r WHERE $where"); $count->execute($params); $pager = paginate((int) $count->fetchColumn());
$stmt = $pdo->prepare("SELECT r.id, r.title, r.status, r.report_count, r.download_count, r.created_at, u.full_name, c.code FROM resources r JOIN users u ON u.id = r.user_id JOIN courses c ON c.id = r.course_id WHERE $where ORDER BY r.created_at DESC LIMIT ? OFFSET ?");
foreach ($params as $i => $p) $stmt->bindValue($i + 1, $p); $stmt->bindValue(count($params) + 1, $pager['per_page'], PDO::PARAM_INT); $stmt->bindValue(count($params) + 2, $pager['offset'], PDO::PARAM_INT); $stmt->execute(); $rows = $stmt->fetchAll(); $page_title = 'Resources'; require __DIR__ . '/../includes/header.php';
?>
<div class="page-header"><div><h1>Resources</h1><p class="muted">Moderate published, reported and removed files.</p></div><form method="get"><label for="status" class="sr-only">Status</label><select id="status" name="status" onchange="this.form.submit()"><?php foreach ($allowed as $item): ?><option value="<?= e($item) ?>"<?= $status === $item ? ' selected' : '' ?>><?= e(ucfirst(str_replace('_', ' ', $item))) ?></option><?php endforeach; ?></select></form></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Resource</th><th>Uploader</th><th>Status</th><th>Reports</th><th>Downloads</th><th>Actions</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><a href="<?= e(url('resource_details.php?id=' . $row['id'])) ?>"><?= e($row['title']) ?></a><br><span class="muted"><?= e($row['code']) ?></span></td><td><?= e($row['full_name']) ?></td><td><?= status_badge($row['status']) ?></td><td><?= (int) $row['report_count'] ?></td><td><?= (int) $row['download_count'] ?></td><td><?php if (in_array($row['status'], ['removed', 'under_review'], true)): ?><form method="post" action="<?= e(url('actions/admin/restore_resource.php')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="resource_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm" type="submit">Restore</button></form><?php endif; ?><?php if ($row['status'] !== 'removed'): ?><form method="post" action="<?= e(url('actions/admin/remove_resource.php')) ?>" class="inline-form" data-confirm="Remove this resource?"><?= csrf_field() ?><input type="hidden" name="resource_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm btn-danger" type="submit">Remove</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?= render_pagination($pager) ?>
<?php require __DIR__ . '/../includes/footer.php'; ?>
